insert into public.profiles (id, role, handle, display_name, tagline, bio, city, lat, lng, genres, links, verified, act_type, members_count, fee_min, fee_max, set_length_min, open_to_door_deals, tech_needs, venue_type, capacity, address, has_stage, has_sound_system, has_piano, equipment, budget_min, budget_max, music_nights, followers_count, bring_count) values
  ('00000000-0000-4000-8000-000000000001', 'artist', 'noa.band', 'נועה והלהקה', 'סול ישראלי חם עם כלי נשיפה', 'חמישה נגנים, זמרת אחת ואהבה גדולה לסול של שנות ה־70. מנגנים חומרים מקוריים בעברית ומחווה לגדולים.', 'תל אביב', 32.07, 34.78, array['soul', 'israeli']::text[], '{}'::jsonb, true, 'band', 5, 2500, 6000, 90, true, 'מערכת הגברה ל־5 ערוצים, 2 מוניטורים', null, null, null, null, null, null, null, null, null, null, 1840, 312),
  ('00000000-0000-4000-8000-000000000002', 'artist', 'maya.kol', 'מאיה קול', 'שירים שקטים לערבים רועשים', 'יוצרת, גיטרה ופסנתר. מופיעה בבתי קפה ובסלונים קטנים, אוהבת קהל שמקשיב.', 'תל אביב', 32.06, 34.77, array['singer_songwriter', 'acoustic']::text[], '{}'::jsonb, false, 'solo', 1, 800, 1800, 60, true, null, null, null, null, null, null, null, null, null, null, null, 920, 141),
  ('00000000-0000-4000-8000-000000000003', 'artist', 'port.trio', 'שלישיית הנמל', 'ג׳אז סטנדרטים ומקור', 'פסנתר, קונטרבס ותופים. שני סטים של 50 דקות, מתאים למסעדות ולברים עם אווירה.', 'יפו', 32.05, 34.75, array['jazz']::text[], '{}'::jsonb, true, 'ensemble', 3, 1500, 3500, 120, false, 'פסנתר (או קלידים 88), נקודת חשמל, פינה של 3x2 מטר', null, null, null, null, null, null, null, null, null, null, 1310, 98),
  ('00000000-0000-4000-8000-000000000004', 'artist', 'dj.orna', 'DJ אורנה', 'גרוב, דיסקו ופאנק מהוויניל', 'סטים של ויניל בלבד. גרוב, דיסקו ופאנק — לברים, גגות ומסיבות שקיעה.', 'תל אביב', 32.08, 34.77, array['electronic', 'soul']::text[], '{}'::jsonb, false, 'dj', 1, 1200, 3000, 180, true, null, null, null, null, null, null, null, null, null, null, null, 2650, 207),
  ('00000000-0000-4000-8000-000000000005', 'artist', 'roi.acoustic', 'רועי אקוסטי', 'קאברים ישראליים בגיטרה וקול', 'שירים שכולם מכירים, בעיבודים שעוד לא שמעתם. מושלם לערבי שישי.', 'חיפה', 32.81, 34.99, array['israeli', 'acoustic']::text[], '{}'::jsonb, false, 'solo', 1, 600, 1400, 90, true, null, null, null, null, null, null, null, null, null, null, null, 470, 64),
  ('00000000-0000-4000-8000-000000000006', 'artist', 'lia.margalit', 'ליה ומרגלית', 'דואו פולק בהרמוניות', 'שתי גיטרות, שני קולות, הרבה סיפורים. שירים מקוריים בעברית ובאנגלית.', 'ירושלים', 31.77, 35.21, array['folk', 'singer_songwriter']::text[], '{}'::jsonb, false, 'duo', 2, 1000, 2200, 75, true, null, null, null, null, null, null, null, null, null, null, null, 680, 120),
  ('00000000-0000-4000-8000-000000000007', 'artist', 'jaffa.nights', 'הלילות של יפו', 'מזרחית־ים־תיכונית לרקוד', 'עוד, כינור, דרבוקה ובס. מהפיוטים ועד ההיטים — מופע שמרים את כל האולם.', 'יפו', 32.052, 34.755, array['mizrahi', 'world']::text[], '{}'::jsonb, true, 'band', 6, 3500, 8000, 120, true, null, null, null, null, null, null, null, null, null, null, null, 3120, 455),
  ('00000000-0000-4000-8000-000000000008', 'artist', 'bluebird.blues', 'בלובירד', 'בלוז חשמלי מהדלתא לדרום תל אביב', null, 'תל אביב', 32.055, 34.775, array['blues', 'rock']::text[], '{}'::jsonb, false, 'band', 4, 2000, 4500, 90, true, null, null, null, null, null, null, null, null, null, null, null, 760, 88),
  ('00000000-0000-4000-8000-000000000101', 'venue', 'basement.yermi', 'המרתף של ירמי', 'בר מרתף עם במה קטנה ואוזניים גדולות', 'בר מרתף אינטימי. הופעות חיות 4 ערבים בשבוע, קהל שבא לשמוע.', 'תל אביב', 32.0628, 34.7725, array['jazz', 'blues', 'rock']::text[], '{}'::jsonb, true, null, null, null, null, null, null, null, 'bar', 80, 'רחוב הרצל 12, תל אביב', true, true, false, 'מערכת 2kW, מיקסר 12 ערוצים, 3 מוניטורים, ערכת תופים בסיסית', 1000, 3500, 'רביעי–שבת', 1430, 0),
  ('00000000-0000-4000-8000-000000000102', 'venue', 'harbor.loft', 'לופט הנמל', 'לופט תעשייתי מול הים', 'חלל של 300 מ״ר עם תקרה גבוהה ונוף לים. מתאים להשקות, מסיבות והופעות גדולות.', 'יפו', 32.0545, 34.7505, array['electronic', 'world', 'indie']::text[], '{}'::jsonb, false, null, null, null, null, null, null, null, 'loft', 220, 'שדרות הנמל 3, יפו', true, true, false, null, 3000, 9000, 'חמישי–שבת', 2210, 0),
  ('00000000-0000-4000-8000-000000000103', 'venue', 'alma.teahouse', 'בית התה של אלמה', 'תה, עוגה ושירים בשקט', 'בית קפה קטן עם פסנתר עומד. הופעות אקוסטיות בלבד.', 'תל אביב', 32.0735, 34.7812, array['acoustic', 'singer_songwriter', 'folk']::text[], '{}'::jsonb, false, null, null, null, null, null, null, null, 'cafe', 40, 'רחוב שיינקין 40, תל אביב', false, true, true, null, 500, 1500, 'שלישי, שישי בצהריים', 640, 0),
  ('00000000-0000-4000-8000-000000000104', 'venue', 'carmel.roof', 'גג הכרמל', 'שקיעה, קוקטיילים ו־DJ', null, 'חיפה', 32.8136, 34.9893, array['electronic', 'soul', 'pop']::text[], '{}'::jsonb, false, null, null, null, null, null, null, null, 'bar', 150, 'שדרות הנשיא 120, חיפה', false, true, false, null, 1500, 4000, 'חמישי–שבת', 980, 0),
  ('00000000-0000-4000-8000-000000000105', 'venue', 'nachlaot.porch', 'מרפסת נחלאות', 'מסעדה שכונתית עם חצר', null, 'ירושלים', 31.7795, 35.2085, array['folk', 'world', 'jazz']::text[], '{}'::jsonb, false, null, null, null, null, null, null, null, 'restaurant', 70, 'רחוב בצלאל 8, ירושלים', false, true, false, null, 800, 2500, 'חמישי', 520, 0),
  ('00000000-0000-4000-8000-000000000106', 'venue', 'zehava.salon', 'סלון זהבה', 'סלון תרבות בדירה ישנה', 'סלון ביתי לתרבות. ישיבה על כריות, קהל קשוב, כניסה בכרטיסים.', 'תל אביב', 32.0668, 34.7741, array['singer_songwriter', 'classical', 'jazz']::text[], '{}'::jsonb, false, null, null, null, null, null, null, null, 'gallery', 50, 'רחוב לילינבלום 25, תל אביב', false, false, true, null, 0, 1200, 'ראשון, רביעי', 410, 0),
  ('00000000-0000-4000-8000-000000000201', 'fan', 'dana.live', 'דנה', null, null, 'תל אביב', null, null, array['jazz', 'soul', 'indie']::text[], '{}'::jsonb, false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 0, 0)
