insert into public.posts (id, profile_id, body, encore_count, created_at) values
  ('00000000-0000-4000-a000-000000000001', '00000000-0000-4000-8000-000000000001', 'חזרות אחרונות לפני ההשקה בלופט הנמל. הכלי נשיפה נשמעים כמו חלום 🎺', 214, now() - interval '3 hours'),
  ('00000000-0000-4000-a000-000000000002', '00000000-0000-4000-8000-000000000101', 'מחפשים להקת בלוז/רוק לחמישי בסוף החודש. דיל ׳הגבוה מביניהם׳, קהל של 80. שלחו הצעה!', 57, now() - interval '6 hours'),
  ('00000000-0000-4000-a000-000000000003', '00000000-0000-4000-8000-000000000002', 'שיר חדש נולד הלילה. אנגן אותו לראשונה מחר בבית התה של אלמה.', 133, now() - interval '20 hours'),
  ('00000000-0000-4000-a000-000000000004', '00000000-0000-4000-8000-000000000004', 'ארגז ויניל חדש הגיע מברלין. נתראה על הגג בחיפה 🌅', 301, now() - interval '30 hours'),
  ('00000000-0000-4000-a000-000000000005', '00000000-0000-4000-8000-000000000106', 'פתחנו את לוח הסלונים לחודש הבא — יש 3 ערבים פנויים לאמנים אקוסטיים.', 44, now() - interval '50 hours'),
  ('00000000-0000-4000-a000-000000000006', '00000000-0000-4000-8000-000000000007', '240 איש אמרו שמגיעים. לופט הנמל, תתכוננו לרעוד 🥁', 389, now() - interval '72 hours')
